class Solution:
    def batch(self, lengths: list[int], budget: int) -> list[list[int]]:
        batches=[]
        current=[]
        used=0
        for i,length in enumerate(lengths):
            if current and used+length>budget:
                batches.append(current)
                current=[]
                used=0
            current.append(i)
            used+=length
        if current:batches.append(current)
        return batches

